function installQfvTooltips(doc){
  // A single overlay in the report document, independent of the provider page.
  const win=doc.defaultView,tip=doc.createElement('div');tip.id='qfv-tooltip';tip.hidden=true;tip.setAttribute('aria-hidden','true');doc.body.appendChild(tip);
  let active=null;
  function hide(){active=null;tip.hidden=true;tip.textContent='';}
  function place(x,y,anchor){
    const pad=8,gap=12,w=doc.documentElement.clientWidth,h=doc.documentElement.clientHeight;
    const r=tip.getBoundingClientRect();
    const left=Math.max(pad,Math.min(x+gap,w-r.width-pad));
    const below=anchor?anchor.bottom+gap:y+gap,above=anchor?anchor.top-r.height-gap:y-r.height-gap;
    const top=Math.max(pad,Math.min(below+r.height<=h-pad?below:above,h-r.height-pad));
    tip.style.left=left+'px';tip.style.top=top+'px';
  }
  function show(e,x,y,anchor){active=e;tip.textContent=e.getAttribute('data-help')||'';tip.hidden=false;place(x,y,anchor);}
  function focusTip(e){const r=e.getBoundingClientRect();show(e,r.left,r.bottom,r);}
  for(const e of doc.querySelectorAll('.qfv-help[data-help]')){
    e.removeAttribute('title'); // Avoid a second native tooltip in the live dashboard.
    e.addEventListener('pointerenter',ev=>show(e,ev.clientX,ev.clientY));
    e.addEventListener('pointermove',ev=>{if(active===e)place(ev.clientX,ev.clientY);});
    e.addEventListener('pointerleave',()=>{if(active===e)hide();});
    e.addEventListener('focus',()=>focusTip(e));
    e.addEventListener('blur',()=>{if(active===e)hide();});
    e.addEventListener('click',ev=>{ev.preventDefault();ev.stopPropagation();if(active!==e)focusTip(e);});
    e.addEventListener('keydown',ev=>{if(ev.key==='Escape'){hide();ev.preventDefault();ev.stopPropagation();}});
  }
  doc.addEventListener('scroll',hide,true);win.onresize=hide;win.onblur=hide;
}
