  const dist=add(split,'div','qfv-query-distribution');const bar=add(dist,'div','qfv-scope-track');add(bar,'i','qfv-webbar').style.width=(totalQ?openQ/totalQ*100:0)+'%';add(bar,'i','qfv-sitebar').style.width=(totalQ?siteQ/totalQ*100:0)+'%';const leg=add(dist,'div','qfv-scope-labels');help(add(leg,'span','',(missing?'N/A':openQ)+' Open-web'),'','No explicit site hostname restriction in the recovered query.');help(add(leg,'span','',(missing?'N/A':siteQ)+' Site-scoped'),'','Explicit site hostname restriction, optionally including a URL path.');
